#ifndef SOUND_H
#define SOUND_H

/*
 * Sound synthesis: creates every sound effect and the menu music as
 * raw audio samples, using simple 8-bit style waveforms.
 *
 * All sounds are generated by this code (no recorded audio files),
 * so they are original work covered by the project's MIT licence.
 *
 * This module only produces numbers; it never touches an audio
 * device, so it can be unit tested. audio.c plays the result.
 */

/* Samples per second, mono, signed 16-bit. */
#define SOUND_SAMPLE_RATE 22050

typedef enum {
    SOUND_KEY,            /* a letter is typed                     */
    SOUND_DELETE,         /* backspace / DEL / CLEAR               */
    SOUND_CLICK,          /* a button is pressed                   */
    SOUND_INVALID,        /* guess too short or not in word list   */
    SOUND_TILE_CORRECT,   /* one green tile revealed               */
    SOUND_TILE_PRESENT,   /* one yellow tile revealed              */
    SOUND_TILE_ABSENT,    /* one grey tile revealed                */
    SOUND_WIN,
    SOUND_LOSE,
    SOUND_COUNT           /* number of effects (not a sound)       */
} SoundEffect;

/*
 * Render an effect into a newly allocated buffer (*samples).
 * Returns the number of samples, or 0 if memory ran out or the
 * effect is unknown. The caller frees *samples with free().
 */
int sound_render_effect(SoundEffect effect, short **samples);

/*
 * Render one loop of the menu music the same way. The last sample
 * flows straight back into the first, so it can repeat forever.
 */
int sound_render_music(short **samples);

#endif
